<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post('name');$price=(float)post('price');$stock=(float)post('stock');$min=(float)post('min_quantity');if(!$name||!post('description')||$price<=0||$stock<0||$min<=0||($stock>0&&$min>$stock))$error='Check the required fields, price, stock, and minimum quantity.';else{try{$image=null;if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];$type=mime_content_type($f['tmp_name']);if($f['error']||$f['size']>MAX_UPLOAD||!in_array($type,['image/jpeg','image/png','image/webp'],true))throw new Exception('Upload a JPG, PNG, or WebP image under 2 MB.');if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$type];$filename=bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$filename))throw new Exception('Could not save the image. Check uploads/products permissions.');$image='uploads/products/'.$filename;}db()->prepare('INSERT INTO products(seller_id,category_id,name,description,image_path,price,stock,min_quantity,freshness_info,is_available) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$sid,(int)post('category_id'),$name,post('description'),$image,$price,$stock,$min,post('freshness_info'),isset($_POST['is_available'])]);flash('success','Fish listing created.');redirect('seller/products.php');}catch(Throwable $e){$error=$e->getMessage();}}}$pageTitle='Add listing';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER CATALOGUE</p><h1>Add fresh fish</h1></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><?php require 'product-form.php';require '../includes/footer.php'; ?>
